t="# -*- coding: utf-8 -*-\nfrom pathlib import Path\nfrom datetime import datetime,timezone\nimport json\nr=Path('/Users/nerea/Documents/Proyectos/MEE/mee-web');plan=json.load(open(r/'wordpress/plugins/mee-editorial/data/production-plan.json'));ls=(r.parent/'MEE_Plan_Editorial_840_entradas.md').read_text().splitlines()\nstyle='Use case: stylized-concept. Original MEE editorial illustration, tactile layered cut-paper sculpture, matte cobalt blue #1547BB, vivid red #EF383E accents, warm ivory #F7F6F2, soft studio light, generous margins. No text, digits, letters, logos, brands, flags, watermarks, currency signs, official seals, UI or statistical graphs. One original independent scene, entirely fictional. '\nscenes={'E4.12.14': [('Exactly seven broad ascending ivory paper steps with generous spacing, a single cobalt paper wrench resting on the final top step with a small red accent. A seven-day introductory practice-plan metaphor, no certification, mastery guarantee, success badge, digits or letters. Landscape1200:630.', 'Siete peldaños marfil de papel que conducen a una llave azul, como metáfora de un plan de práctica.'), ('A small fictional paper project on an ivory desk: one cobalt open box, three separate ivory folded components and one simple red paper tool. A limited practice task, no real product, actual app UI, measurements, data or guarantees. Landscape1600:900.', 'Proyecto pequeño de papel sobre una mesa: caja azul, tres piezas marfil y una herramienta roja.'), ('An open ivory paper notebook shows seven blank broad page tabs with no markings, one cobalt pencil and one red bookmark. Daily practice journal metaphor, no dates, scores, calendar numbers, words or letters. Landscape1600:900.', 'Cuaderno abierto con siete pestañas sin texto, un lápiz azul y un marcador rojo.')], 'E4.12.15': [('One circular cobalt paper radar sculpture on ivory ground with exactly four separate red raised dots around its interior and one plain ivory radial arm. Editorial watchlist metaphor, no real signals, statistical graph, prediction, ranking, geographic borders, digits or text. Landscape1200:630.', 'Radar circular azul de papel con cuatro puntos rojos separados y un brazo radial marfil.'), ('An unfolded ivory paper map with several broad cobalt paths, one plain red junction marker, no geographic outline or real location. Possible routes metaphor, no investment or travel recommendation, precise routes, charts, text or digits. Landscape1600:900.', 'Mapa ficticio de papel marfil con caminos azules y un punto de encuentro rojo.'), ('A fictional adult paper figure in cobalt clothing stands on an ivory hill looking toward a broad abstract horizon through a plain red paper telescope. Reflection on uncertain technology futures, no real person, location, stars, brand, predictions, text or digits. Landscape1600:900.', 'Figura ficticia azul sobre una colina que observa un horizonte abstracto con un catalejo rojo.')], 'E6.3.01': [('A fictional eighteenth-century pin-making workshop built entirely from tactile paper, with three distinct adult artisan figures in simple period-inspired clothing carrying out separate pin-making tasks along one ivory bench, small blue and red paper tools and several large stylized pin shapes. Historical conceptual illustration, not a verified reenactment of Smith’s specific shop, not actual production quantities, no machinery schematics, wages, text, digits or logos. Landscape1200:630.', 'Taller histórico ficticio de papel con tres artesanos adultos que realizan tareas distintas junto a un banco.'), ('Exactly three interlocking large paper gears on ivory ground, two cobalt and one red; the centers contain one simple hand silhouette, one plain blank clock circle without hands or marks, and one basic tool silhouette. Dexterity, saved transition time and machinery metaphor, no actual technical mechanism, numerical productivity, text or digits. Landscape1600:900.', 'Tres engranajes azules y rojo con símbolos de destreza, tiempo y herramienta.'), ('An abstract ivory paper market opens outward in broad folds revealing several small cobalt stall silhouettes with a red path connecting them, generous margins. Market extent metaphor, not a real city, actual scale, growing revenue chart, borders, brands, words, digits or flags. Landscape1600:900.', 'Mercado ficticio de papel marfil que se abre en pliegues con puestos azules y un camino rojo.')]}\nfor row in [x for x in plan if 659<=x['number']<=661]:\n i=row['id'];d=r/'editorial/articles'/i;assert not d.exists();d.mkdir();(d/'sources').mkdir();j=row['source_line']-1;assert i in ls[j];k=next(z for z in range(j+1,len(ls))if ls[z].startswith('#### ')or ls[z].startswith('## '));(d/'brief-original.md').write_text('\\n'.join(ls[j:k]).strip()+'\\n');tags=[row['topic'],{'Fundamentos':'fundamentos','Desarrollo':'desarrollo','Aplicación':'aplicacion'}[row['level']]]\n x=dict(row,planned_tags=tags,phase='research_preparation_images_pending',article_complete=False,sources_verified=False,images_complete=False,images_generated=0,published=False,images_visually_checked=False,review_status='RESEARCH_PENDING',pending=['Fuentes primarias actuales por verificar con fechas y alcance.','Tres originales image_gen, texto, revisión, atribución del argumento contrario y publicación pendientes.'],updated_at=datetime.now(timezone.utc).isoformat())\n prompts={};images={}\n for role,(scene,alt)in zip(['featured','interior-1','interior-2'],scenes[i]):\n  file=i.lower().replace('.','-')+('-destacada.webp'if role=='featured'else'-'+role+'.webp');prompts[role]=dict(prompt=style+scene,file=file,width=1200 if role=='featured'else 1600,height=630 if role=='featured'else 900);images[role]=dict(file=file,title=alt,alt=alt,caption='')\n for name,obj in [('research.json',x),('metadata-draft.json',dict(x,images=images)),('image-prompts.json',prompts),('source-preparation.json',dict(id=i,phase='RESEARCH_PENDING',sources_verified=False,article_complete=False,images_complete=False))]:(d/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\\n')\n (d/'research-notes.md').write_text('# Preparación · '+i+'\\n\\nBrief y prompts conservados. Fuentes, tres imágenes, texto y publicación pendientes. No cuenta como terminada.\\n');print(i,row['number'],tags)\n"
